"""Runner for the shared compiler-generated bytecode vector suites."""
from __future__ import annotations
import json, math, pathlib, sys, tempfile, shutil, os, io
from dataclasses import dataclass
from typing import Any, List
from .errors import LmcodeError, HostError
from .loader import load
from .registry import Context, ObjectRef, Registry
from .vm import _format_g15
from .stdlib import Collection, JsonNode
from .results import ResultSink, success_frame, failure_frame

@dataclass
class Thing:
    id: int
class IntList(list): pass
def _json_value(value):
    if isinstance(value,ObjectRef): value=value.value
    if isinstance(value,Collection): value=value.value
    if isinstance(value,JsonNode): value=value.json_value()
    if isinstance(value,Thing): raise HostError("lmcode return: object values are not JSON-compatible")
    if isinstance(value,list): return [_json_value(v) for v in value]
    if isinstance(value,dict):
        converted={}
        for key,item in value.items():
            try: text=_host_text(key)
            except Exception: raise HostError("lmcode return: invalid JSON value at : utf8")
            converted[text]=_json_value(item)
        return converted
    if type(value) is int:
        if abs(value)>9007199254740991: raise HostError("lmcode return: invalid JSON value at : unsafe_integer")
        return value
    if type(value) is float:
        if not math.isfinite(value): raise HostError("lmcode return: invalid JSON value at : nonfinite")
        if value.is_integer() and abs(value)>9007199254740991: raise HostError("lmcode return: invalid JSON value at : unsafe_integer")
        return 0.0 if value==0 else value
    if value is None or type(value) in (str,bool): return value
    if hasattr(value,"json_value"): return value.json_value()
    raise HostError("lmcode return: invalid JSON value at : handle")

def _display(value):
    if isinstance(value,ObjectRef): value=value.value
    if isinstance(value,Thing): return "thing "+str(value.id)
    if type(value) is bool: return "bool "+("true" if value else "false")
    if type(value) is int: return "int "+str(value)
    if type(value) is float: return "float "+_format_g15(value)
    if type(value) is str: return "string "+value
    return "void" if value is None else "object"
def _host_text(value):
    try: return value.encode("latin-1").decode("utf-8", "strict")
    except (UnicodeEncodeError, UnicodeDecodeError): return value

def _parse_arg(value):
    if isinstance(value,dict) and value.get("type")=="Thing":
        obj=Thing(int(value["id"])); return ObjectRef("Thing",obj,id(obj))
    return value

def _vm_hex(value): return _vm_bytes(value).hex()
def _vm_bytes(value): return value.encode("latin-1")
def _decode_hex(value):
    if len(value)%2 or any(c not in "0123456789abcdef" for c in value): raise HostError("bytes: expected lowercase hexadecimal pairs")
    return bytes.fromhex(value)

def _make_std_int_list():
    from .stdlib import _make_collection
    return _make_collection("IntList",[0,1,2,3])

class Host:
    def __init__(self,include_std=False):
        self.registry=Registry(include_std=include_std); self.trace=[]; self.sink=ResultSink(); self.output=io.BytesIO(); self.temp_dir=tempfile.mkdtemp(prefix="lmcode-conformance-") if include_std else os.getcwd(); r=self.registry
        for name,typ in (("t","Trace"),("root","Thing"),("v","Var"),("xs","IntList")): r.context(name,typ)
        def method(owner,name,params,returns,fn): r.method(owner,name,params,returns,lambda ctx,self_obj,args:fn(self_obj,args))
        def function(name,params,returns,fn,dry_callback=None,_raw=False): r.function(name,params,returns,lambda ctx,self_obj,args:fn(args),dry_callback,_raw=_raw)
        for name,typ,fmt in (("int","int",lambda x:"int "+str(x)),("int","float",lambda x:"float "+_format_g15(x)),("float","float",lambda x:"float "+_format_g15(x)),("str","string",lambda x:"str "+_host_text(x)),("bool","bool",lambda x:"bool "+("true" if x else "false")),("thing","Thing",lambda x:"thing "+str(x.id))):
            r.method("Trace",name,[typ],"void",lambda ctx,self_obj,args,f=fmt:self.trace.append(f(args[0].value if isinstance(args[0],ObjectRef) else args[0])))
        r.method("Trace","status",[],"Status",lambda ctx,self_obj,args:"OPTIMAL")
        r.method("Trace","hex",["string"],"void",lambda ctx,self_obj,args:self.trace.append("hex "+_vm_hex(args[0])),_raw=True)
        method("Thing","len",[],"int",lambda s,a:self.len_thing(s))
        method("Thing","at",["int"],"Thing",lambda s,a:self.at_thing(a[0]))
        method("Thing","id",[],"int",lambda s,a:s.id)
        method("Thing","next",[],"Thing",lambda s,a:self.obj("Thing",Thing(s.id+1)))
        method("Thing","name",[],"string",lambda s,a:"thing-"+str(s.id))
        method("Thing","scaled",["float"],"float",lambda s,a:float(s.id)*a[0])
        method("Thing","plus",["Thing"],"Thing",lambda s,a:self.obj("Thing",Thing(s.id+a[0].id)))
        method("Thing","minus",["Thing"],"Thing",lambda s,a:self.obj("Thing",Thing(s.id-a[0].id)))
        method("Thing","times",["int"],"Thing",lambda s,a:self.obj("Thing",Thing(s.id*a[0])))
        method("Thing","neg",[],"Thing",lambda s,a:self.obj("Thing",Thing(-s.id)))
        method("Thing","rminus",["int"],"Thing",lambda s,a:self.obj("Thing",Thing(a[0]-s.id)))
        method("Thing","set",["int"],"Thing",lambda s,a:self.set_thing(s,a[0]))
        method("Var","id",[],"int",lambda s,a:s.id)
        method("Var","expr",[],"Thing",lambda s,a:self.expr(s.id))
        function("var",["int"],"Var",lambda a:self.var(a[0]))
        function("thing",["int"],"Thing",lambda a:self.obj("Thing",Thing(a[0])))
        function("twice",["int"],"int",lambda a:a[0]*2); function("twice",["float"],"float",lambda a:a[0]*2.0)
        function("half",["float"],"float",lambda a:a[0]/2.0); function("bound",["int"],"int",lambda a:self.bound(a[0]))
        function("yes",[],"bool",lambda a:self.yes()); function("fail",["string"],"void",lambda a:self.fail(a[0]))
        function("bad_int",[],"int",lambda a:"x")
        if not include_std:
            method("IntList","len",[],"int",lambda s,a:len(s)); method("IntList","at",["int"],"int",lambda s,a:s[a[0]])
        function("bytes",["string"],"string",lambda a:_decode_hex(a[0]),_raw=True)
        function("test_temp_dir",[],"string",lambda a:self.temp_dir)
        function("test_long_path",[],"string",lambda a:self.long_path())
        function("printed",[],"string",lambda a:self.output.getvalue(),_raw=True)
        if include_std:
            from .stdlib import Collection, JsonNode, register_testing
            register_testing(r, self.output)
        if not include_std:
            for typ in ("int","float","bool","string","Json","StrList","IntList","FloatList","StrMap","IntMap","FloatMap"):
                function("lmcode_return_set",[typ],"void",lambda a:self.sink.set(a[0]),dry_callback=None)
                function("lmcode_return_put",["string",typ],"void",lambda a:self.sink.put(a[0],a[1]),dry_callback=None)
            function("lmcode_return_null",[],"void",lambda a:self.sink.set(None))
            function("lmcode_return_put_null",["string"],"void",lambda a:self.sink.put(a[0],None))
    def obj(self,t,v): return ObjectRef(t,v,id(v))
    def long_path(self):
        path=pathlib.Path(self.temp_dir)
        for _ in range(12): path=path/"segment-0123456789abcdef"
        path.mkdir(parents=True,exist_ok=True)
        return str(path/"résumé-文件-😀.bin")
    def cleanup(self):
        if self.temp_dir!=os.getcwd(): shutil.rmtree(self.temp_dir,ignore_errors=True)
    def len_thing(self,s): self.trace.append("len "+str(s.id)); return s.id
    def at_thing(self,n): self.trace.append("at "+str(n)); return self.obj("Thing",Thing(n))
    def set_thing(self,s,n): s.id=n; return self.obj("Thing",s)
    def expr(self,n): self.trace.append("expr "+str(n)); return self.obj("Thing",Thing(n))
    def var(self,n): self.trace.append("var "+str(n)); return self.obj("Var",Thing(n))
    def bound(self,n): self.trace.append("bound "+str(n)); return n
    def yes(self): self.trace.append("yes"); return True
    def fail(self,m): raise HostError(m)
    def context(self):
        c=Context(); c.set("t",object()); c.set("root",Thing(0)); c.set("v",Thing(0))
        c.set("xs",_make_std_int_list() if self.registry.std_enabled else IntList([0,1,2,3]))
        c.result_sink=self.sink; return c

def _trace_matches(actual,expected):
    if len(actual)!=len(expected): return False
    for got,want in zip(actual,expected):
        if not want.startswith("~ "):
            if got!=want:return False
        else:
            body=want[2:]; i=body.rfind(" "); prefix=body[:i+1]
            try:a,b=float(got[len(prefix):]),float(body[i+1:])
            except (ValueError,IndexError):return False
            if not got.startswith(prefix) or not math.isfinite(a) or not math.isfinite(b) or abs(a-b)>1e-12*max(abs(b),1e-300):return False
    return True

def run_suite(directory,include_std=False):
    root=pathlib.Path(directory); manifest=json.loads((root/"manifest.json").read_text(encoding="utf-8")); passed=0; failures=[]
    for vector in manifest["vectors"]:
        name=vector["name"]
        try:
            lines=(root/(name+".expect")).read_text(encoding="utf-8").splitlines(); kind=lines[0]; raw_tail=lines[1:]
            sink_expect=None
            for i,line in enumerate(raw_tail):
                if line.startswith("sink "): sink_expect=json.loads(line[5:]); raw_tail=raw_tail[:i]; break
            tail=[x.replace("\\n","\n") for x in raw_tail]
            schema=(root/vector.get("schema",manifest.get("schema","schema.json"))).read_bytes(); code=(root/vector["bytecode"]).read_bytes(); host=Host(include_std)
            try: program=load(code,schema,host.registry)
            except LmcodeError as err:
                if kind!="load_error" or len(tail)<2 or err.code!=tail[0] or tail[1] not in err.message: raise AssertionError("load error mismatch: "+err.code+" "+err.message)
                passed+=1; continue
            if kind=="load_error": raise AssertionError("mutated load vector was accepted")
            context=host.context()
            if kind=="entries":
                actual=[e.name+" "+e.annotation+" "+e.interface for e in program.entries]
                if actual!=tail: raise AssertionError("entries mismatch: "+repr(actual))
            elif kind in ("call","call_error","call_error_at"):
                error=None
                entry_name,raw=tail[0].split(" ",1); values=json.loads(raw); entry=next(e for e in program.entries if e.name==entry_name)
                args=[_parse_arg(x) for x in values]; program.run(context,host.registry)
                try: result=program.call(entry_name,context,host.registry,args)
                except LmcodeError as err:
                    error=err
                    if kind=="call_error":
                        if err.code!=tail[1] or tail[2] not in err.message: raise AssertionError("call error mismatch: "+err.code+" "+err.message)
                        result=None
                    elif kind=="call_error_at":
                        if err.code!=tail[1] or err.line!=int(tail[2]) or err.column!=int(tail[3]) or tail[4] not in err.message: raise AssertionError("located call error mismatch: "+repr(err))
                        result=None
                    else: raise
                if kind=="call":
                    if _display(result)!=tail[1].removeprefix("result "): raise AssertionError("entry result mismatch: "+_display(result)+" != "+tail[1])
                    if not _trace_matches(host.trace,tail[2:]): raise AssertionError("entry trace mismatch: "+repr(host.trace))
            else:
                try: program.run(context,host.registry); error=None
                except LmcodeError as err:error=err
                if kind=="trace":
                    if error: raise error
                    if not _trace_matches(host.trace,tail): raise AssertionError("trace mismatch: "+repr(host.trace))
                elif kind=="runtime_error":
                    if error is None or tail[0] not in error.message: raise AssertionError("runtime error mismatch: "+(error.message if error else "success"))
                elif kind=="runtime_error_at":
                    if error is None or error.code!=tail[0] or error.line!=int(tail[1]) or error.column!=int(tail[2]) or tail[3] not in error.message: raise AssertionError("located runtime error mismatch: "+repr(error))
                elif kind=="runtime_error_exact":
                    message=error.message if error else ""
                    if error and error.line: message=message.removeprefix("dsl line "+str(error.line)+(":"+str(error.column) if error.column else "")+": ")
                    if error is None or error.code!=tail[0] or message!=tail[1]: raise AssertionError("exact runtime error mismatch: "+repr(error))
                elif kind=="runtime_error_file":
                    message=error.message if error else ""
                    if error and error.line: message=message.removeprefix("dsl line "+str(error.line)+(":"+str(error.column) if error.column else "")+": ")
                    if error is None or error.code!=tail[0] or tail[1]+": " not in message or tail[2] not in message or not message.rsplit(":",1)[-1].strip(): raise AssertionError("file runtime error mismatch: "+repr(error))
                else:raise AssertionError("unknown expectation kind "+kind)
            if sink_expect is not None:
                if host.sink.json()!=sink_expect["json"]: raise AssertionError("sink mismatch: "+host.sink.json())
                actual_frame=failure_frame(error) if error is not None else success_frame(json.loads(host.sink.json()))
                if actual_frame!=sink_expect["frame"]: raise AssertionError("result frame mismatch: "+repr(actual_frame)+" != "+repr(sink_expect["frame"]))
            passed+=1
        except Exception as error: failures.append((name,error))
        finally:
            if "host" in locals() and host is not None: host.cleanup()
    for name,error in failures: print("FAIL "+name+": "+str(error),file=sys.stderr)
    total=len(manifest["vectors"]); print(("PASS " if not failures else "FAIL ")+str(passed)+"/"+str(total)+" vectors")
    return 0 if not failures and passed==total and total>0 else 1

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: python -m lmcode.conformance VECTOR_DIRECTORY", file=sys.stderr)
        raise SystemExit(2)
    raise SystemExit(run_suite(sys.argv[1], True))
